const incoming = $input.first().json;
if (incoming.headers?.['x-nexus-secret'] !== $env.N8N_SECRET) throw new Error('Invalid webhook secret');
const body = incoming.body || incoming;
for (const key of ['review_id', 'product_name', 'rating', 'comment']) if (body[key] === undefined || body[key] === null) throw new Error(`Missing ${key}`);
const prompt = `You are a professional customer-support agent. Analyse this product review and reply directly to the customer. Return only JSON: {sentiment: positive|neutral|negative, urgency: low|medium|high, support_reply: string}. The reply must be empathetic, specific, under 120 words, and must not invent refunds, policy, or delivery facts. Product: ${body.product_name}. Rating: ${body.rating}/5. Review: ${body.comment}`;
return [{ json: { review_id: body.review_id, geminiBody: { contents: [{ parts: [{ text: prompt }] }], generationConfig: { responseMimeType: 'application/json' } } } }];

const raw = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text;
if (!raw) throw new Error('Gemini returned no review analysis');
const result = JSON.parse(raw);
const source = $('Prepare review analysis').first().json;
return [{ json: { review_id: source.review_id, sentiment: ['positive','neutral','negative'].includes(result.sentiment) ? result.sentiment : 'neutral', urgency: ['low','medium','high'].includes(result.urgency) ? result.urgency : 'low', support_reply: String(result.support_reply || '').slice(0, 2000) } }];
